package plates.core.validators

import plates.core.validators.PlateCheck
import plates.core.validators.RuledPlateValidator
import plates.core.values.PlateSpec
import plates.core.values.PlateTextGroup

/** The verdict on a plate; [reason] explains an invalid one and is null when valid. */
public data class PlateValidation(val reason: String? = null) {
    val isValid: Boolean get() = reason == null

    public companion object {
        public val valid: PlateValidation = PlateValidation()
        public fun invalid(reason: String): PlateValidation = PlateValidation(reason)
    }
}

/** A plate as it stands, for a validator to judge. */
public class PlateEntry(public val spec: PlateSpec, public val values: List<String?>, public val activeIndex: Int? = null) {
    /** Canonical value of the group named [key]; '' if none. */
    public fun group(key: String): String = spec.valueOfGroup(key, values)

    public val activeGroup: PlateTextGroup? get() = activeIndex?.let(spec::groupAt)
}

// ASCII only: Char.isDigit() accepts every Unicode Nd.
public fun isDigits(value: String): Boolean = value.isNotEmpty() && value.all { it in '0'..'9' }

// Code units, safe because isDigits passes ASCII alone.
public fun isDigitsOfLength(value: String, length: Int): Boolean = value.length == length && isDigits(value)

// ASCII A-Z only, min..max long.
public fun isLetters(value: String, min: Int, max: Int = min): Boolean = value.length in min..max && value.all { it in 'A'..'Z' }

/** Judges a plate. It never prevents input; what to do with the verdict is the host's decision. */
public fun interface PlateValidator {
    public fun validate(entry: PlateEntry): PlateValidation
}

/** The verdict a spec's restrictions give on [entry], or null when none is broken. */
public fun restrictionVerdict(entry: PlateEntry): PlateValidation? =
    entry.spec.restrictionViolatedBy(entry.values)?.let { PlateValidation.invalid(it.reason) }

/** Quiet until [gateGroup], the last register the user reaches, has content. */
public abstract class GatedPlateValidator : PlateValidator {
    public abstract val gateGroup: String

    public abstract fun judge(entry: PlateEntry): PlateValidation

    override fun validate(entry: PlateEntry): PlateValidation =
        restrictionVerdict(entry) ?: if (entry.group(gateGroup).isEmpty()) PlateValidation.valid else judge(entry)
}

/** One field rule of a [RuledPlateValidator]: the group named [group] must match [pattern] whole, or the plate is invalid
 * for [reason]. An [optional] group may also be empty. Keep classes explicit (`[0-9]`, not `\d`) so only ASCII passes. */
public class PlateCheck(public val group: String, pattern: String, public val reason: String, private val optional: Boolean = false) {
    private val re = Regex(pattern)

    public fun passes(value: String): Boolean = (optional && value.isEmpty()) || re.matches(value)
}

/** A gated validator that is a list of [checks], judged in order; the first to fail gives the verdict. The gate is [gate],
 * else the last check's group. */
public abstract class RuledPlateValidator(private val gate: String? = null) : GatedPlateValidator() {
    public abstract val checks: List<PlateCheck>

    override val gateGroup: String get() = gate ?: checks.last().group

    override fun judge(entry: PlateEntry): PlateValidation =
        checks.firstOrNull { !it.passes(entry.group(it.group)) }?.let { PlateValidation.invalid(it.reason) } ?: PlateValidation.valid
}
